syntax:
template <class T, class Deleter = std::default_delete<T>>
class unique_ptr {
public:
  // ... other members ...
  ~unique_ptr() { if (get()) deleter_(ptr_); }
private:
  T* ptr_;
  Deleter deleter_;
};

code_example:
#include <iostream>
#include <memory>
struct MyResource {
  ~MyResource() { std::cout << "MyResource destroyed\n"; }
};
struct MyDeleter {
  void operator()(MyResource* ptr) {
    std::cout << "MyDeleter called\n";
    // Perform custom cleanup (e.g., file closing, network release)
    delete ptr; 
  }
};
int main() {
  std::unique_ptr<MyResource, MyDeleter> resource(new MyResource());
  // ... use resource ...
  return 0;
}
